// e2e/performance/lighthouse.spec.ts
import { test, expect } from '@playwright/test';
import { playAudit } from 'playwright-lighthouse';
import { loginAs } from '../fixtures/auth';

const PAGES_TO_TEST = [
  { path: '/admin/dashboard', name: 'Admin Dashboard' },
  { path: '/dosen/dashboard', name: 'Dosen Dashboard' },
  { path: '/mahasiswa/dashboard', name: 'Mahasiswa Dashboard' },
  { path: '/admin/titles', name: 'Admin Titles' },
  { path: '/login', name: 'Login' },
];

test.describe('Lighthouse Performance Audit', () => {
  for (const page of PAGES_TO_TEST) {
    test(`${page.name} passes Lighthouse audit`, async ({ page: p }) => {
      // Login first if needed
      if (!page.path.includes('login')) {
        await loginAs(p, 'admin');
      }

      await p.goto(page.path);
      await p.waitForLoadState('networkidle');

      await playAudit({
        page: p,
        thresholds: {
          performance: 90,
          accessibility: 95,
          'best-practices': 90,
          seo: 90,
        },
        port: 9222,
      });
    });
  }
});
